// Shift a lowercase letter forward by k (k >= 0), wrapping z -> a.
// Anything that is not a-z is returned unchanged.
char shift_letter(char c, int k) {
    // TODO: c - 'a' is 0..25; shift it, wrap with % 26, convert back to a char

    // check if c is a valid character
    if (c < 'a' || 'z' < c) {
        return c;
    }
    int offset = (c - 'a' + k) % 26;
    c = static_cast<char>('a' + offset);
    return c;
}

